/// Shared model parameters: the 2-element casadi parameter vector p
/// (initial values from the acados JSON).  The JSON carries no
/// parameter names, so p is a single fixed-size Eigen matrix leaf,
/// shared by the dynamics model and the cost / constraint code, and
/// exposed through the problem's params() hook (settable by name "p"
/// via the inspect protocol).
struct NP2Params
{
    Eigen::Matrix<double, 2, 1> p;

    NP2Params()
    {
        p << 1.0, 0.5;
    }

    template <class Visitor>
    static constexpr void inspect(Visitor&& vis)
    {
        vis("p", &NP2Params::p);
    }
};

struct NP2Ode
{
    using P = ocp::Problem<NP2Dims>;
    using state_t   = typename P::state_t;
    using control_t = typename P::control_t;
    using dyn_df_dx_t = typename P::dyn_df_dx_t;
    using dyn_df_du_t = typename P::dyn_df_du_t;

    detail::NP2Dyn dyn_;
    NP2Params params_;

    NP2Params& params()
    {
        return params_;
    }

    const NP2Params& params() const
    {
        return params_;
    }

    // xdot = f_expl(x, u, t) directly from the explicit ODE function.
    state_t f(const state_t& x, const control_t& u, double t) const
    {
        state_t r;
        dyn_.eval(x.data(), u.data(), nullptr, params_.p.data(), t, r.data());
        return r;
    }

    // Central finite differences of f(x, u, t) w.r.t. x and u.
    void jacobian(const state_t& x, const control_t& u, double t,
                  dyn_df_dx_t& df_dx, dyn_df_du_t& df_du) const
    {
        const double h = 1.0e-6;
        for (int j = 0; j < P::nx; ++j)
        {
            state_t xp = x, xm = x;
            xp(j) += h;
            xm(j) -= h;
            df_dx.col(j) = (f(xp, u, t) - f(xm, u, t)) / (2.0 * h);
        }
        for (int j = 0; j < P::nu; ++j)
        {
            control_t up = u, um = u;
            up(j) += h;
            um(j) -= h;
            df_du.col(j) = (f(x, up, t) - f(x, um, t)) / (2.0 * h);
        }
    }
};

using NP2Integ =
    ocp::ExplicitRkIntegrator<NP2Dims, NP2Ode,
                              ocp::K4Tag, 1>;

class NP2
    : public ocp::ContinuousProblem<NP2Integ>
{
    using Base = ocp::ContinuousProblem<NP2Integ>;

public:
    NP2() : Base(NP2Ode{}, 0.1)
    {
        cpVx_ = Eigen::Map<const Eigen::Matrix<double, 2, 2>>(cpVx_data);
        cpW_ = Eigen::Map<const Eigen::Matrix<double, 2, 2>>(cpW_data);
        cpyref_ << 0.0, 0.0;
        cpVu_ = Eigen::Map<const Eigen::Matrix<double, 2, 1>>(cpVu_data);
        ctVx_ = Eigen::Map<const Eigen::Matrix<double, 2, 2>>(ctVx_data);
        ctW_ = Eigen::Map<const Eigen::Matrix<double, 2, 2>>(ctW_data);
        ctyref_ << 0.0, 0.0;
    }

    /// Shared model parameters (the 2-element casadi parameter
    /// vector), owned by the dynamics model; forwarded so host-side / MEX
    /// writes through params() reach the live object the dynamics and the
    /// cost / constraint code read.
    NP2Params& params()
    {
        return Base::ode().params();
    }

    const NP2Params& params() const
    {
        return Base::ode().params();
    }

    static constexpr double inf_ =
        std::numeric_limits<double>::infinity();

    state_t cost_reference() const
    {
        return cpyref_.head<2>();
    }

    double stage_cost_value(int k, const state_t& x,
                            const control_t& u) const
    {
        return cp_value(x, u, 0.1 * k);
    }

    void stage_cost_value_grad(int k, const state_t& x,
                               const control_t& u, double& value,
                               stage_grad_t& grad) const
    {
        value = cp_value(x, u, 0.1 * k);
        grad = cp_grad(x, u, 0.1 * k);
    }

    void stage_cost_value_grad_hess(int k, const state_t& x,
                                    const control_t& u, double& value,
                                    stage_grad_t& grad,
                                    stage_hess_t& hess) const
    {
        stage_cost_value_grad(k, x, u, value, grad);
        hess = cp_hess(x, u, 0.1 * k);
    }

    double terminal_cost_value(const state_t& x) const
    {
        return ct_value(x, 0.30000000000000004);
    }

    void terminal_cost_value_grad(const state_t& x, double& value,
                                  term_grad_t& grad) const
    {
        value = ct_value(x, 0.30000000000000004);
        grad = ct_grad(x, 0.30000000000000004);
    }

    void terminal_cost_value_grad_hess(const state_t& x, double& value,
                                       term_grad_t& grad,
                                       term_hess_t& hess) const
    {
        terminal_cost_value_grad(x, value, grad);
        hess = ct_hess(x, 0.30000000000000004);
    }


    double cp_value(const state_t& x, const control_t& u,
                          double /*t*/) const
    {
        const Eigen::Matrix<double, 2, 1> y = cpVx_ * x + cpVu_ * u - cpyref_;
        return 0.5 * y.dot(cpW_ * y);
    }

    stage_grad_t cp_grad(const state_t& x, const control_t& u,
                               double /*t*/) const
    {
        const Eigen::Matrix<double, 2, 1> y = cpVx_ * x + cpVu_ * u - cpyref_;
        const Eigen::Matrix<double, 2, 1> g = cpW_ * y;
            stage_grad_t r;
            r.head<2>() = cpVx_.transpose() * g;
            r.tail<1>() = cpVu_.transpose() * g;
            return r;
    }

    stage_hess_t cp_hess(const state_t& /*x*/, const control_t& /*u*/,
                               double /*t*/) const
    {
            stage_hess_t H;
            H.topLeftCorner(2, 2) = cpVx_.transpose() * cpW_ * cpVx_;
            H.topRightCorner(2, 1) = cpVx_.transpose() * cpW_ * cpVu_;
            H.bottomLeftCorner(1, 2) = cpVu_.transpose() * cpW_ * cpVx_;
            H.bottomRightCorner(1, 1) = cpVu_.transpose() * cpW_ * cpVu_;
            return H;
    }
    double ct_value(const state_t& x, double /*t*/) const
    {
        const Eigen::Matrix<double, 2, 1> y = ctVx_ * x - ctyref_;
        return 0.5 * y.dot(ctW_ * y);
    }

    term_grad_t ct_grad(const state_t& x, double /*t*/) const
    {
        const Eigen::Matrix<double, 2, 1> y = ctVx_ * x - ctyref_;
        const Eigen::Matrix<double, 2, 1> g = ctW_ * y;
            return ctVx_.transpose() * g;
    }

    term_hess_t ct_hess(const state_t& /*x*/, double /*t*/) const
    {
            return ctVx_.transpose() * ctW_ * ctVx_;
    }

private:
    static constexpr double cpVx_data[4] = {
    1.0, 0.0, 0.0, 1.0
    };
    static constexpr double cpW_data[4] = {
    1.0, 0.0, 0.0, 1.0
    };
    static constexpr double cpVu_data[2] = {
    0.0, 0.0
    };
    static constexpr double ctVx_data[4] = {
    1.0, 0.0, 0.0, 1.0
    };
    static constexpr double ctW_data[4] = {
    1.0, 0.0, 0.0, 1.0
    };



    Eigen::Matrix<double, 2, 2> cpVx_{};
    Eigen::Matrix<double, 2, 2> cpW_{};
    Eigen::Matrix<double, 2, 1> cpyref_{};
    Eigen::Matrix<double, 2, 1> cpVu_{};
    Eigen::Matrix<double, 2, 2> ctVx_{};
    Eigen::Matrix<double, 2, 2> ctW_{};
    Eigen::Matrix<double, 2, 1> ctyref_{};
};

